using UnityEngine;using NWH.WheelController3D;using LWS.TruckTaxi;using LWS.InterstateHauler;
namespace LWS.TruckSports {
// Scene-local weather semantics over the existing Taxi/Weatherade renderer and real NWH contacts.
public sealed class SportsSnowSurface:MonoBehaviour {
 public SportsChaosWeather weather;public SportsEventSession session;public LWS.TruckCheeseRolling.CheeseWeather cheese;public LWS.TruckBaseJumping.BaseJumpMatch baseJump;public TruckTaxiSnowSurface surface;public LwsWeatheradeAdapter adapter;public WheelController[] wheels;public Rigidbody[] broadBodies;public ParticleSystem[] spray;public Texture2D snowTexture,detailTexture,sparkleTexture;public Shader[] retainedShaders;public int depthRenderer=1;
 public float Coverage{get;private set;}public int Contacts{get;private set;}public int BroadContacts{get;private set;}public bool Falling{get;private set;}
 Rigidbody[] wheelBodies,traceBodies;SportsSnowBodyContact[] supports;float[] widths;bool[] mattress,tireBody;public int ScrapeContacts{get;private set;}Vector3[] prior;bool[] contact;float refresh;int stamp=int.MinValue,sprayCursor;bool wasRunning,observing;
 void Start(){surface.ConfigureVendorTextures(snowTexture,detailTexture,sparkleTexture);surface.ConfigureDepthRenderer(depthRenderer);surface.Initialize(new TruckTaxiSnowRegion(.3f),adapter);wheelBodies=new Rigidbody[wheels.Length];var powered=new System.Collections.Generic.HashSet<Rigidbody>();var broad=new System.Collections.Generic.HashSet<Rigidbody>(broadBodies);for(int i=0;i<wheels.Length;i++){wheelBodies[i]=wheels[i].GetComponentInParent<Rigidbody>();if(wheelBodies[i]!=null)powered.Add(wheelBodies[i]);}var tracked=new System.Collections.Generic.List<Rigidbody>();foreach(var body in FindObjectsByType<Rigidbody>(FindObjectsInactive.Include))if(body.gameObject.scene==gameObject.scene&&body.mass>=.05f&&body.GetComponentInParent<TruckTaxiPedestrian>()==null)tracked.Add(body);traceBodies=tracked.ToArray();supports=new SportsSnowBodyContact[traceBodies.Length];widths=new float[traceBodies.Length];mattress=new bool[traceBodies.Length];tireBody=new bool[traceBodies.Length];for(int i=0;i<traceBodies.Length;i++){var body=traceBodies[i];var support=body.GetComponent<SportsSnowBodyContact>();if(support==null)support=body.gameObject.AddComponent<SportsSnowBodyContact>();support.enabled=false;supports[i]=support;mattress[i]=broad.Contains(body);tireBody[i]=powered.Contains(body);float width=.25f;foreach(var c in body.GetComponentsInChildren<Collider>(true))if(!c.isTrigger&&c.attachedRigidbody==body)width=Mathf.Max(width,Mathf.Min(c.bounds.size.x,c.bounds.size.z));widths[i]=mattress[i]?3.15f:Mathf.Clamp(width,.2f,3.15f);}prior=new Vector3[wheels.Length+traceBodies.Length];contact=new bool[prior.Length];}
 bool Running=>session!=null?session.Running:cheese!=null&&cheese.match.InMatch;bool Live=>session!=null?session.Live:cheese!=null&&cheese.match.Live;
 void LateUpdate(){Falling=weather!=null?(weather.Kind==SportsWeatherKind.Snow||weather.Kind==SportsWeatherKind.Blizzard):cheese!=null?cheese.Kind==LWS.TruckCheeseRolling.CheeseWeatherKind.Blizzard:baseJump!=null&&baseJump.option==2;int current=weather!=null?weather.Seed:cheese!=null?cheese.match.Round:baseJump!=null?baseJump.Round:0;bool running=Running;if(current!=stamp||running&&!wasRunning){stamp=current;Coverage=Falling?.68f:0;surface.RefreshStreamedSurfaces();System.Array.Clear(contact,0,contact.Length);}wasRunning=running;if(Live)Coverage=Mathf.Clamp01(Coverage+Time.deltaTime*(Falling?.018f:-.025f));surface.SetCoverage(Coverage);if(Time.time>=refresh){surface.Refresh();refresh=Time.time+.25f;}Contacts=BroadContacts=ScrapeContacts=0;if(!Live||Coverage<.06f){StopTraces();return;}SetObserving(true);int emitted=0;for(int i=0;i<wheels.Length;i++){var w=wheels[i];if(w==null||!w.enabled||!w.gameObject.activeInHierarchy||!w.IsGrounded||w.HitCollider==null||w.HitNormal.y<.25f||!surface.IsSnowCoveredOffRoad(w.HitCollider,w.HitPoint,wheelBodies[i]!=null?wheelBodies[i].transform:w.transform)){Stop(i);continue;}Trace(i,w.HitPoint,Mathf.Max(.16f,w.wheel.width),wheelBodies[i],ref emitted);Contacts++;}
 for(int b=0;b<traceBodies.Length;b++){int index=wheels.Length+b;var body=traceBodies[b];var support=supports[b];if(body==null||body.isKinematic||!body.gameObject.activeInHierarchy||!support.Supported||tireBody[b]&&!mattress[b]&&body.transform.up.y>.65f||!surface.IsSnowCoveredOffRoad(support.Surface,support.Point,body.transform)){Stop(index);continue;}Trace(index,support.Point,widths[b],body,ref emitted);if(mattress[b])BroadContacts++;else ScrapeContacts++;}}

 void Trace(int i,Vector3 p,float width,Rigidbody body,ref int emitted){if(!contact[i]||(p-prior[i]).sqrMagnitude>=16){prior[i]=p;contact[i]=true;surface.StopWheelTrace(i);return;}var from=prior[i];if((p-from).sqrMagnitude<.0025f){surface.StopWheelTrace(i);return;}surface.TraceWheel(i,from,p,width,Coverage*.3f,true);float speed=body!=null?body.GetPointVelocity(p).magnitude:0;if(spray.Length>0&&speed>1&&emitted++<8){var fx=spray[sprayCursor++%spray.Length];fx.transform.position=p+Vector3.up*.08f;var emit=new ParticleSystem.EmitParams{velocity=Vector3.up*Mathf.Clamp(speed*.12f,.25f,2)-Vector3.ClampMagnitude(body.linearVelocity,10)*.1f};fx.Emit(emit,Mathf.Clamp(Mathf.RoundToInt(speed*.3f),1,5));}prior[i]=p;contact[i]=true;}
 void Stop(int i){surface.StopWheelTrace(i);contact[i]=false;}void SetObserving(bool value){if(observing==value)return;observing=value;if(supports!=null)foreach(var support in supports)if(support!=null)support.enabled=value;}public void StopTraces(){SetObserving(false);if(contact==null)return;for(int i=0;i<contact.Length;i++)Stop(i);}void OnDisable(){StopTraces();if(spray!=null)foreach(var p in spray)if(p!=null)p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
}}
